# "saved_reports" holds reports someone chose to keep -- generated by hand from the
# Report page, or automatically once a month by the scheduled job -- so there's a real
# standing record instead of a one-off download that's gone the moment the browser tab
# closes. Mirrors report_store.py's saved_reports table from the original.
class CreateSavedReports < ActiveRecord::Migration[8.1]
  def change
    create_table :saved_reports do |t|
      # Same meaning as on analysis_snapshots: how many days back this report covers,
      # and which audience it was filtered/framed for.
      t.integer :days, null: false
      t.string :audience, null: false

      # The rendered report itself, always stored as Markdown -- the same "most natural
      # format for actually handing to a therapist" reasoning the original used, and it
      # keeps this table simple (one text column) instead of needing to store four
      # different renderings of every saved report.
      t.text :content, null: false

      # "scheduled" or "manual" -- purely informational, shown on the saved reports
      # list so it's obvious which reports appeared on their own vs. were requested.
      t.string :source, null: false

      t.references :user, null: false, foreign_key: true

      t.timestamps
    end

    add_index :saved_reports, :created_at
  end
end
